#include "images/image_mock.h"
#include "../src/card_image_transfer.c"
static struct bt_conn peer={.security=4};
static int display_requests,hold_calls;
int env_telemetry_ble_hold_connection(struct bt_conn*c,uint32_t ms){assert(c==&peer&&ms==120000);++hold_calls;return 0;}
void env_telemetry_ble_release_connection(struct bt_conn*c){assert(c==&peer);}
int sd_logger_storage_begin(void){assert(!mounted&&!image_lock.held);mounted=1;if(storage_hook)storage_hook();return 0;}
int sd_logger_storage_end(void){assert(mounted);mounted=0;return 0;}
int card_display_set_image_file(const char*p){assert(!strcmp(p,IMAGE_PREFIX));++display_requests;return 0;}
int card_display_register_image_file(const char*p){assert(!strcmp(p,IMAGE_PREFIX));return 0;}
int card_display_set_mode(enum card_display_mode mode){(void)mode;return 0;}
static void step_worker(void){if(!setjmp(worker_done))image_worker(NULL,NULL,NULL);assert(!busy&&!image_lock.held&&!mounted);}
static void reset(void){assert(!peer.refs);memset(files,0,sizeof(files));state=0;received=0;token=0;expected_crc=0;busy=false;commit_decided=false;initialized=true;image_requested.count=0;owner=NULL;operation_token=0;last_length=0;storage_hook=NULL;write_hook=NULL;display_requests=0;fs_writes=0;mock_now=0;}
static uint32_t data_crc(void){uint8_t block[256];memset(block,0x12,sizeof(block));uint32_t c=0;for(size_t i=0;i<CARD_IMAGE_BYTES;i+=sizeof(block))c=image_crc32(c,block,MIN(sizeof(block),CARD_IMAGE_BYTES-i));return c;}
static void command(uint8_t op,uint32_t id){uint8_t p[8]={'I','C',1,op};image_put32(p+4,id);assert(write_control(&peer,NULL,p,8,0,0)==8);}
static void begin(uint32_t id){uint8_t p[20]={'I','C',1,1};image_put32(p+4,id);image_put32(p+8,CARD_IMAGE_BYTES);image_put32(p+12,data_crc());p[16]=0x90;p[17]=1;p[18]=0x58;p[19]=2;assert(write_control(&peer,NULL,p,20,0,0)==20);}
static void status_while_blocked(void){uint8_t result[24];int before=fs_writes;int64_t now=mock_now;assert(read_status(&peer,NULL,result,24,0)==24);assert(result[3]==IMAGE_PREPARING||result[3]==IMAGE_COMMITTING);assert(mock_now==now&&fs_writes==before);mock_now+=14000;storage_hook=NULL;}
static void make_old_image(void){files[0].exists=true;files[0].length=120032;memset(files[0].data+32,0x11,120000);image_file_header(files[0].data,image_crc32(0,files[0].data+32,120000),10,true);}
static void upload(bool retry){int before=fs_writes;begin(7);assert(state==IMAGE_PREPARING&&fs_writes==before);storage_hook=status_while_blocked;step_worker();assert(state==IMAGE_RECEIVING&&received==0);for(uint32_t off=0;off<CARD_IMAGE_BYTES;){uint8_t p[244]={'I','D',1,0};size_t n=MIN(CARD_IMAGE_MAX_CHUNK,CARD_IMAGE_BYTES-off);image_put32(p+4,7);image_put32(p+8,off);memset(p+12,0x12,n);assert(write_data(&peer,NULL,p,n+12,0,0)==(ssize_t)n+12);assert(received==off);step_worker();assert(received==off+n);if(retry){int writes=fs_writes;assert(write_data(&peer,NULL,p,n+12,0,0)==(ssize_t)n+12);assert(!busy&&fs_writes==writes&&received==off+n);}off+=n;}assert(rolling_crc==data_crc());}
static void abort_before_decision(void){storage_hook=NULL;command(3,7);}
static void abort_on_tag(off_t offset,size_t length){if(offset==20&&length==4){write_hook=NULL;uint8_t p[8]={'I','C',1,3};image_put32(p+4,7);assert(commit_decided&&write_control(&peer,NULL,p,8,0,0)<0);}}
static void test_protocol(void){assert(image_crc32(0,(const uint8_t*)"123456789",9)==0xcbf43926U);uint32_t c=image_crc32(0,(const uint8_t*)"1234",4);assert(image_crc32(c,(const uint8_t*)"56789",5)==0xcbf43926U);uint8_t p[244]={'I','D',1,0};image_put32(p+4,1);memset(p+12,0x12,232);struct card_image_chunk chunk;assert(!image_decode_chunk(p,244,&chunk));p[12]=0x44;assert(image_decode_chunk(p,244,&chunk)==-EINVAL);p[12]=0x12;p[3]=1;assert(image_decode_chunk(p,244,&chunk)==-EINVAL);p[3]=0;image_put32(p+8,119999);assert(image_decode_chunk(p,14,&chunk)==-EINVAL);uint8_t h[32];image_file_header(h,123,1,false);assert(image_check_header(h)==-EBADMSG);image_file_header(h,123,1,true);assert(!image_check_header(h));h[24]=1;assert(image_check_header(h)==-EBADMSG);}
static void test_upload(void){reset();upload(true);command(2,7);assert(state==IMAGE_COMMITTING);storage_hook=status_while_blocked;step_worker();assert(state==IMAGE_STORED&&display_requests==1);uint32_t display_token=card_image_display_started();assert(state==IMAGE_DISPLAYING);card_image_display_result(display_token,0);assert(state==IMAGE_DISPLAYED&&!peer.refs);static uint8_t frame[120000];assert(!card_image_load_file(IMAGE_PREFIX,frame,sizeof(frame)));assert(frame[0]==0x12&&frame[119999]==0x12);}
static void test_cancel(void){reset();make_old_image();upload(false);assert(files[0].data[32]==0x11);command(2,7);storage_hook=abort_before_decision;step_worker();assert(state==IMAGE_IDLE&&!display_requests&&!peer.refs);assert(image_get32(files[1].data+20)==0);static uint8_t frame[120000];assert(!card_image_load_file(IMAGE_PREFIX,frame,sizeof(frame)));assert(frame[0]==0x11);}
static void test_irreversible_commit(void){reset();make_old_image();upload(false);command(2,7);write_hook=abort_on_tag;step_worker();assert(state==IMAGE_STORED&&display_requests==1&&image_get32(files[1].data+20)==CARD_IMAGE_COMMITTED);uint32_t display_token=card_image_display_started();card_image_display_result(display_token,0);assert(!peer.refs&&files[0].data[32]==0x11);}
static void test_timeout_disconnect(void){reset();make_old_image();begin(7);mock_now=120000;transfer_expired(NULL);step_worker();assert(state==IMAGE_ERROR&&image_error==-ETIMEDOUT&&!peer.refs&&fs_writes==0);begin(8);step_worker();image_disconnected(&peer,19);assert(state==IMAGE_ERROR&&image_error==-ECONNRESET&&!peer.refs);static uint8_t frame[120000];assert(!card_image_load_file(IMAGE_PREFIX,frame,sizeof(frame))&&frame[0]==0x11);}
static void test_corruption_fallback(void){reset();make_old_image();upload(false);command(2,7);step_worker();uint32_t display_token=card_image_display_started();card_image_display_result(display_token,0);files[1].data[32]=0x22;static uint8_t frame[120000];assert(!card_image_load_file(IMAGE_PREFIX,frame,sizeof(frame))&&frame[0]==0x11);files[0].data[32]=0x44;assert(card_image_load_file(IMAGE_PREFIX,frame,sizeof(frame))==-ENOENT);}
static void test_stale_display(void){reset();upload(false);command(2,7);step_worker();uint32_t old=card_image_display_started();mock_now=transfer_deadline;transfer_expired(NULL);assert(!peer.refs&&state==IMAGE_ERROR);upload(false);command(2,7);step_worker();uint32_t current=card_image_display_started();assert(current!=old);card_image_display_result(old,0);assert(state==IMAGE_DISPLAYING&&peer.refs==1);card_image_display_result(current,0);assert(state==IMAGE_DISPLAYED&&!peer.refs);}
int main(void){test_protocol();test_upload();test_cancel();test_irreversible_commit();test_timeout_disconnect();test_corruption_fallback();test_stale_display();puts("Card image PASS: async persisted ack, status during slow I/O, CRC/palette, duplicate data, cancellable/irreversible commit boundary, timeout/disconnect, old-slot fallback, stale display completion ignored.");}
